export const slug = "usb-switch-shared-keyboard-webcam";
export const title = "How to Share a Keyboard and Webcam With a USB Switch";
export const metaTitle = "Share a Keyboard and Webcam With a USB Switch";
export const metaDescription = "Choose and arrange a USB sharing switch around host connections, camera support, call continuity, and safe device switching.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-10-28";
export const readTime = "11 min";
